globalThis.AilyMath={
  confusion(rows,threshold){let tp=0,fp=0,tn=0,fn=0;for(const r of rows){if(r.score>=threshold){r.label?tp++:fp++}else{r.label?fn++:tn++}}return {tp,fp,tn,fn,precision:tp+fp?tp/(tp+fp):null,recall:tp+fn?tp/(tp+fn):null};},
  gradient(w,rate){return w-rate*2*(w-3);},
  clusterStep(points,centroids){const labels=points.map(p=>centroids.map(c=>(p[0]-c[0])**2+(p[1]-c[1])**2).reduce((best,d,i,ds)=>d<ds[best]?i:best,0));const next=centroids.map((c,i)=>{const group=points.filter((_,j)=>labels[j]===i);return group.length?[group.reduce((s,p)=>s+p[0],0)/group.length,group.reduce((s,p)=>s+p[1],0)/group.length]:c;});const inertia=points.reduce((s,p,i)=>s+(p[0]-next[labels[i]][0])**2+(p[1]-next[labels[i]][1])**2,0);return {centroids:next,labels,inertia};},
  irisSplit(rows){let seed=42;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};const train=[],test=[];for(const label of ['setosa','versicolor','virginica']){const group=rows.filter(r=>r.label===label).map(r=>({...r}));for(let i=group.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[group[i],group[j]]=[group[j],group[i]]}train.push(...group.slice(0,35));test.push(...group.slice(35))}return {train,test};},
  knn(train,test,k){const labels=['setosa','versicolor','virginica'],means=Array.from({length:4},(_,j)=>train.reduce((s,r)=>s+r.x[j],0)/train.length),scales=means.map((m,j)=>Math.sqrt(train.reduce((s,r)=>s+(r.x[j]-m)**2,0)/train.length)||1);const matrix=Array.from({length:3},()=>[0,0,0]);const predictions=test.map(r=>{const near=train.map((t,i)=>({label:t.label,i,d:t.x.reduce((s,x,j)=>s+((x-r.x[j])/scales[j])**2,0)})).sort((a,b)=>a.d-b.d||a.i-b.i).slice(0,k);const votes=labels.map(l=>near.filter(n=>n.label===l).length);const pred=labels[votes.indexOf(Math.max(...votes))];matrix[labels.indexOf(r.label)][labels.indexOf(pred)]++;return pred;});return {predictions,matrix,accuracy:predictions.filter((p,i)=>p===test[i].label).length/test.length,means,scales};}
};
